#!/usr/bin/env node
/**
 * A crash during the cache-restore branch of fetchPlexLibrary() shows the error screen
 * instead of leaving the loading screen frozen forever (a support report, "web tuner
 * stuck at 139 of 139"). The cache-restore branch used to have no try/catch of its own:
 * an exception anywhere after the library loaded from the saved cache (filtering,
 * schedule building, autogenerated channels, render) left LL.hide() never called and
 * nothing in the console. The real trigger that reporter hit is unreproduced; this proves
 * the safety net, not a named cause.
 *
 * Loads the real plex-tuner.html, headless, against a Jellyfin-shaped server. Connects
 * once (saves a library cache), then reloads with a flag set so autoGenerateChannels
 * throws on the SECOND load only, the one that takes the cache-restore branch. Negative
 * control: the same page with fetchPlexLibrary reverted to the branch's old shape (the
 * cache-restore work outside any try/catch), which must leave the loading screen up and
 * never show the error screen.
 *
 * Needs Playwright (not a dependency): PLAYWRIGHT=/path/to/playwright/index.mjs, or a
 * resolvable `playwright`. Run: `npm run test:cache-restore-crash`.
 */
import http from "node:http";
import { readFileSync, existsSync, statSync } from "node:fs";
import { extname, join, normalize } from "node:path";

const { chromium } = await import(process.env.PLAYWRIGHT || "playwright");
const root = new URL("../", import.meta.url).pathname;

const film = (n, title, genres) => ({
  Id: `f${n}`, Name: title, Type: "Movie", ProductionYear: 1990 + n, Genres: genres,
  OfficialRating: "PG-13", RunTimeTicks: 5400000000, ProviderIds: {},
  DateCreated: new Date().toISOString(),
  MediaSources: [{ Id: `f${n}`, Container: "mp4", RunTimeTicks: 5400000000,
    MediaStreams: [{ Type: "Video", Codec: "h264", Height: 720, Index: 0 }, { Type: "Audio", Codec: "aac", Index: 1 }] }],
});
const library = Array.from({ length: 10 }, (_, i) => film(i, `Reel ${i + 1}`, ["Action"]));

const jellyfin = http.createServer((req, res) => {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Headers", "*");
  if (req.method === "OPTIONS") { res.writeHead(204); return res.end(); }
  res.writeHead(200, { "Content-Type": "application/json" });
  const url = req.url;
  if (url.startsWith("/System/Info/Public")) return res.end(JSON.stringify({ ServerName: "lab", Version: "10.10.7", ProductName: "Jellyfin Server", Id: "lab" }));
  if (url.startsWith("/UserViews")) return res.end(JSON.stringify({ Items: [{ Id: "movies", Name: "Movies", CollectionType: "movies" }], TotalRecordCount: 1 }));
  if (url.includes("IncludeItemTypes=Movie")) return res.end(JSON.stringify({ Items: library, TotalRecordCount: library.length }));
  res.end(JSON.stringify({ Items: [], TotalRecordCount: 0 }));
});

// The exact pre-fix shape of fetchPlexLibrary's cache-restore branch (no try/catch of its
// own), for the negative control. Reverting to this text on the served page proves the new
// test actually exercises the fix: the same crash, against the old code, must hang instead
// of showing the error screen.
const OLD_BLOCK = `    const cached = await loadLibraryCache(true);
    if (cached && cached.items && cached.items.length > 0) {
      LL.show();
      LL.refreshStepRail(false);
      LL.setPhase('preparing', cached.stale ? 'Cached library' : 'Loading cache');
      await finalizeLibraryWithMusicBrainz(cached.items, { buildAllChannels: LL.isFirstLibraryLoad() });
      LL.hide();
      const firstEnabled = CHANNELS.find(ch => ch.enabled);
      if (firstEnabled) switchChannel(firstEnabled.id);
      if (cached.stale) fetchPlexLibraryFresh();
      return;
    }

    try {
      await fetchLibraryFromServer();
    } catch (err) {
      console.error('Library fetch error:', err);
      globalThis.NostalgexLibraryLoad?.hide();`;

const types = { ".html": "text/html", ".js": "text/javascript", ".cjs": "text/javascript", ".css": "text/css", ".json": "application/json", ".svg": "image/svg+xml" };
const files = http.createServer((req, res) => {
  const p = normalize(join(root, decodeURIComponent(req.url.split("?")[0])));
  if (!p.startsWith(root) || !existsSync(p) || statSync(p).isDirectory()) { res.writeHead(404); return res.end(); }
  let body = readFileSync(p);
  if (p.endsWith("plex-tuner.html")) {
    let text = body.toString()
      .replace(/<script src="https:\/\/cdn\.jsdelivr\.net\/npm\/hls\.js[^>]*><\/script>/, "<script>window.Hls = { isSupported: () => false };</script>")
      // Throws only when the test flag is set, so the first (fresh) load is untouched and
      // only the reload that takes the cache-restore branch hits it.
      .replace(
        "autoGenerateChannels(allItems);",
        "autoGenerateChannels(allItems);\n    if (localStorage.getItem('nx-test-crash-on-cache-restore')) { throw new Error('test: thrown from a post-load step during cache restore'); }",
      );
    if (req.url.includes("preFix")) {
      const reverted = text.replace(
        /\n(\s*)\/\/ Both branches below share this one catch[\s\S]*?console\.error\(`Library fetch error \(\$\{errorSource\}\):`, err\);\n(\s*)globalThis\.NostalgexLibraryLoad\?\.hide\(\);/,
        `\n${OLD_BLOCK}`,
      );
      if (reverted === text) { res.writeHead(500); return res.end("pre-fix anchor not found"); }
      text = reverted;
    }
    body = text;
  }
  res.writeHead(200, { "Content-Type": types[extname(p)] || "application/octet-stream" });
  res.end(body);
});
await new Promise((r) => jellyfin.listen(0, "127.0.0.1", r));
await new Promise((r) => files.listen(0, "127.0.0.1", r));
const api = `http://127.0.0.1:${jellyfin.address().port}`;
const base = `http://127.0.0.1:${files.address().port}`;

let passed = 0;
const failures = [];
const check = (label, ok, detail = "") => { if (ok) passed += 1; else failures.push(`${label}${detail ? `: ${detail}` : ""}`); };

const browser = await chromium.launch({ headless: true });

async function withTimeout(promise, ms) {
  let timer;
  const timeout = new Promise((resolve) => { timer = setTimeout(() => resolve({ timedOut: true }), ms); });
  const result = await Promise.race([promise.then((v) => ({ timedOut: false, v })), timeout]);
  clearTimeout(timer);
  return result;
}

async function run({ query = "" } = {}) {
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  await ctx.route((u) => !u.hostname.match(/^(127\.0\.0\.1|localhost)$/), (route) => route.abort());
  await ctx.addInitScript(([url]) => {
    if (location.pathname.endsWith("plex-tuner.html") && !sessionStorage.getItem("nx-seeded")) {
      sessionStorage.setItem("nx-seeded", "1");
      localStorage.setItem("plex90_saved_auth", JSON.stringify({ token: "t", serverUrl: url, serverName: "lab", backend: "jellyfin", jellyfinUserId: "u" }));
    }
  }, [api]);
  const page = await ctx.newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(String(e).slice(0, 200)));
  const consoleErrors = [];
  page.on("console", (m) => { if (m.type() === "error") consoleErrors.push(m.text().slice(0, 200)); });

  // First load: no crash flag set, builds and saves a library cache normally.
  await page.goto(`${base}/plex-tuner.html${query}`);
  await page.waitForFunction(() => {
    const LL = globalThis.NostalgexLibraryLoad;
    return LL && LL.state.channelBuildTotal > 0 && LL.state.channelBuildIndex >= LL.state.channelBuildTotal;
  }, null, { timeout: 30000 });
  // The library cache is an IndexedDB record now (#152), written after the guide is up. The reload
  // below only takes the cache-restore branch once it has landed.
  await page.waitForFunction(() => new Promise((resolve) => {
    const open = indexedDB.open("nostalgex-library");
    open.onerror = () => resolve(false);
    open.onsuccess = () => {
      const db = open.result;
      if (!db.objectStoreNames.contains("cache")) { db.close(); resolve(false); return; }
      const get = db.transaction("cache").objectStore("cache").get("library");
      get.onsuccess = () => { db.close(); resolve(!!get.result); };
      get.onerror = () => { db.close(); resolve(false); };
    };
  }), null, { timeout: 15000, polling: 250 });
  const loadingHiddenAfterFirst = await page.evaluate(() => document.getElementById("loading-library").style.display === "none");

  // Second load ("went back to it"): sets the crash flag, then reloads so the saved cache
  // is read and the cache-restore branch runs, hitting the injected throw.
  await page.evaluate(() => localStorage.setItem("nx-test-crash-on-cache-restore", "1"));
  await page.reload();
  const result = await withTimeout(
    page.waitForFunction(() => document.getElementById("plex-error-label").style.display === "block", null, { timeout: 15000 }).then(() => true),
    12000,
  );
  const state = await page.evaluate(() => ({
    errorShown: document.getElementById("plex-error-label").style.display === "block",
    errorText: document.getElementById("plex-error-label").textContent,
    connectShown: document.getElementById("plex-connect").style.display === "flex",
    loadingHidden: document.getElementById("loading-library").style.display === "none",
  }));
  await ctx.close();
  return { timedOut: result.timedOut, state, errors, consoleErrors, loadingHiddenAfterFirst };
}

const fixed = await run();
check("fixed: the first load builds normally and hides the loading screen", fixed.loadingHiddenAfterFirst === true);
check("fixed: a crash during cache restore does not time out", fixed.timedOut === false, JSON.stringify(fixed.state));
check("fixed: the error screen shows", fixed.state.errorShown === true, JSON.stringify(fixed.state));
check("fixed: the error screen has text", fixed.state.errorText.length > 0, fixed.state.errorText);
check("fixed: and it does not blame a server that was never asked", !/UNREACHABLE|COULD NOT REACH/.test(fixed.state.errorText), fixed.state.errorText);
check("fixed: the connect screen comes back", fixed.state.connectShown === true, JSON.stringify(fixed.state));
check("fixed: the loading screen is hidden, not left frozen", fixed.state.loadingHidden === true, JSON.stringify(fixed.state));
check("fixed: the crash reaches the page as a caught error, not an uncaught one", fixed.errors.length === 0, fixed.errors.join(" | "));
check("fixed: the console names the branch that failed", fixed.consoleErrors.some((m) => m.includes("cache-restore")), fixed.consoleErrors.join(" | "));

const preFix = await run({ query: "?preFix" });
check("negative control (pre-fix code): the same crash times out instead of showing the error screen", preFix.timedOut === true, JSON.stringify(preFix.state));
check("negative control (pre-fix code): the error screen never shows", preFix.state.errorShown === false, JSON.stringify(preFix.state));
check("negative control (pre-fix code): the loading screen is left up", preFix.state.loadingHidden === false, JSON.stringify(preFix.state));

await browser.close();
jellyfin.close();
files.close();
if (failures.length) {
  console.error(`cache-restore-crash smoke: ${failures.length} failed, ${passed} passed`);
  for (const f of failures) console.error(`  FAIL ${f}`);
  process.exit(1);
}
console.log(`cache-restore-crash smoke: ${passed} checks passed (the fix, and the negative control against the pre-fix code)`);
